export const EDGE_WORKER_FILE_VERSION = "1.0.1";

export const EDGE_WORKER_CODE = "// mint-edge 1.0.1 — Mint's Cloudflare Worker, one file for the Cloudflare dashboard.\n// Paste it whole into Workers → mint-edge → Edit code, then Deploy. Add the variable MINT_KEY (your project key).\n// Guide: Mint → Website setup → Cloudflare, or docs/site-connect/guide/cloudflare-seo-analytics.pdf.\n\n/** mint-edge's small helpers (Workers allow only handlers as the main module's exports). */\n\nconst VERSION = '1.0.1';\n\nconst DEFAULT_API = 'https://mint-c5e1255519fc.herokuapp.com/public/api';\nconst FRESH_MS = 60 * 1000;\nconst STALE_MS = 24 * 60 * 60 * 1000;\nconst WAIT_MS = 1000; // the longest a page waits for Mint when nothing is cached\nconst MAX_REWRITE = 5 * 1024 * 1024;\n\n/* --------------------------------------------------------- small helpers */\n\n/** /about/, /about.html, /about/index.html → /about (as Mint's siteHead pathCandidates). */\nconst pathKey = raw => {\n\tlet p = String(raw || '').split(/[?#]/)[0] || '/';\n\ttry {\n\t\tp = decodeURI(p);\n\t} catch {\n\t\t/* keep it as sent */\n\t}\n\tif (!p.startsWith('/')) p = '/' + p;\n\tp = p.replace(/\\/{2,}/g, '/');\n\tconst bare = p.replace(/\\/index\\.html?$/i, '/').replace(/\\.html?$/i, '');\n\tconst trimmed = bare.length > 1 ? bare.replace(/\\/+$/, '') : bare;\n\treturn trimmed || '/';\n};\n\nconst esc = s => String(s).replace(/&/g, '&amp;').replace(/\"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n\n/** A host the project names (www. and subdomains count), as Mint's /track does. */\nconst hostAllowed = (host, domains, dev) => {\n\tconst h = String(host || '').toLowerCase().replace(/:\\d+$/, '');\n\tif (dev && /^(localhost|127\\.0\\.0\\.1)$/.test(h)) return true;\n\tconst bare = h.replace(/^www\\./, '');\n\treturn (domains || []).some(d => {\n\t\tconst dom = String(d).toLowerCase().replace(/^www\\./, '');\n\t\treturn bare === dom || bare.endsWith(`.${dom}`);\n\t});\n};\n\n/**\n * mint-edge — Mint's Cloudflare Worker (docs/site-connect SC-10).\n *\n * Runs in the customer's own Cloudflare account, on a route like `www.acme.com/*`, in front of their site. Every\n * request goes to their own server exactly as without it (`fetch(request)`); on the way back, an HTML page that's\n * added to Website → SEO in Mint gets Mint's SEO in its <head> — so link previews (Facebook, LinkedIn, WhatsApp, X),\n * which read only the HTML, show it. Every page also gets Mint's analytics script, served from the site's own domain.\n *\n *   /_mint/track.js        Mint's track.js, from the site's own domain (ad blockers pass first-party scripts)\n *   /_mint/api/track       page views → Mint, with the visitor's address\n *   /_mint/api/site/…      tags / head, for track.js\n *   /robots.txt, /sitemap.xml   from Mint, only when switched on (Site setup); the site's own otherwise\n *   redirects               Site setup → Redirects\n *   everything else        the site's own server; HTML 200s get Mint's head + the script\n *\n * Fails open (D9): if Mint is slow or down it uses what it last had, else passes the page through untouched. A\n * site never breaks because of Mint. Settings (Worker variables):\n *   MINT_KEY       the project key (mint_pk_…) — required; without it the Worker only passes requests through\n *   MINT_API       Mint's site API, default https://mint-c5e1255519fc.herokuapp.com/public/api\n *   BYPASS_SECRET  ?mint-bypass=<it> skips the Worker for one request (Mint's before/after check)\n *   ORIGIN, MINT_DEV  local testing only: where the site is, and allow localhost\n */\n\n\nconst apiOf = env => String(env.MINT_API || DEFAULT_API).replace(/\\/+$/, '');\n\n/** The site's own server: the same request (Cloudflare sends it on to the origin), or ORIGIN when testing locally. */\nconst toOrigin = (request, env, url = new URL(request.url)) => {\n\tif (!env.ORIGIN) return fetch(request);\n\tconst o = new URL(env.ORIGIN);\n\tconst u = new URL(url.pathname + url.search, o);\n\treturn fetch(new Request(u, request));\n};\n\nconst withTimeout = async (promise, ms) => {\n\tlet t;\n\ttry {\n\t\treturn await Promise.race([promise, new Promise((_, no) => (t = setTimeout(() => no(new Error('timeout')), ms)))]);\n\t} finally {\n\t\tclearTimeout(t);\n\t}\n};\n\n/* -------------------------------------------- what Mint says, kept a while */\n\n// Per isolate; each entry { at, value }. Fresh for a minute, then used while a new one is fetched in the\n// background, and up to a day when Mint can't be reached.\nconst memo = new Map();\n\nconst askMint = async (env, path) => {\n\tconst res = await fetch(`${apiOf(env)}${path}`, { headers: { 'x-mint-edge': VERSION, accept: 'application/json' } });\n\tif (!res.ok) throw new Error(`Mint ${res.status}`);\n\treturn res.json();\n};\n\nconst remembered = async (ctx, key, load) => {\n\tconst hit = memo.get(key);\n\tconst age = hit ? Date.now() - hit.at : Infinity;\n\tconst refresh = () =>\n\t\tload().then(\n\t\t\tvalue => (memo.set(key, { at: Date.now(), value }), value),\n\t\t\t() => null\n\t\t);\n\tif (age < FRESH_MS) return hit.value;\n\tif (age < STALE_MS) {\n\t\t// Stale: answer with it now and fetch the new one after the page is sent.\n\t\tif (!hit.refreshing) {\n\t\t\thit.refreshing = true;\n\t\t\tctx.waitUntil(refresh().finally(() => (hit.refreshing = false)));\n\t\t}\n\t\treturn hit.value;\n\t}\n\ttry {\n\t\treturn await withTimeout(refresh(), WAIT_MS);\n\t} catch {\n\t\treturn null;\n\t}\n};\n\nconst configOf = (env, ctx) => remembered(ctx, 'config', () => askMint(env, `/site/edge?apiKey=${encodeURIComponent(env.MINT_KEY)}`));\nconst headOf = (env, ctx, key) => remembered(ctx, `head:${key}`, () => askMint(env, `/site/head?apiKey=${encodeURIComponent(env.MINT_KEY)}&path=${encodeURIComponent(key)}`));\n\n/* ------------------------------------------------------- /_mint/* routes */\n\n// Only what track.js calls goes through to Mint.\nconst API_PATHS = { track: ['POST'], 'site/tags': ['GET'], 'site/head': ['GET'] };\n\nconst mintRoute = async (request, env, url) => {\n\tconst api = apiOf(env);\n\tif (url.pathname === '/_mint/track.js') {\n\t\tconst res = await fetch(`${new URL(api).origin}/public/track.js`, { cf: { cacheTtl: 300, cacheEverything: true } });\n\t\treturn new Response(res.body, { status: res.status, headers: { 'content-type': 'application/javascript; charset=utf-8', 'cache-control': 'public, max-age=300' } });\n\t}\n\tconst rest = url.pathname.replace(/^\\/_mint\\/api\\//, '');\n\tif (!API_PATHS[rest]?.includes(request.method)) return new Response('Not found', { status: 404 });\n\tconst headers = new Headers();\n\tfor (const h of ['content-type', 'user-agent', 'referer', 'origin', 'accept-language']) if (request.headers.get(h)) headers.set(h, request.headers.get(h));\n\tconst ip = request.headers.get('cf-connecting-ip');\n\tif (ip) headers.set('x-mint-visitor-ip', ip);\n\theaders.set('x-mint-edge', VERSION);\n\tconst res = await fetch(`${api}/${rest}${url.search}`, { method: request.method, headers, body: request.method === 'POST' ? await request.text() : undefined });\n\tconst out = new Response(res.body, res);\n\tout.headers.delete('access-control-allow-origin');\n\treturn out;\n};\n\n/* ------------------------------------------------------ the page's <head> */\n\n// In <head> only: a <title> in an inline <svg> isn't the page's.\nconst selectorOf = t => `head ${t.tag === 'title' ? 'title' : t.tag === 'link' ? `link[rel=\"${t.rel}\"]` : t.property ? `meta[property=\"${t.property}\"]` : `meta[name=\"${t.name}\"]`}`;\n\nconst tagHtml = t =>\n\tt.tag === 'title'\n\t\t? `<title data-mint-seo=\"edge\">${esc(t.content)}</title>`\n\t\t: t.tag === 'link'\n\t\t? `<link rel=\"${esc(t.rel)}\" href=\"${esc(t.content)}\" data-mint-seo=\"edge\">`\n\t\t: `<meta ${t.property ? `property=\"${esc(t.property)}\"` : `name=\"${esc(t.name)}\"`} content=\"${esc(t.content)}\" data-mint-seo=\"edge\">`;\n\n// JSON-LD can't hold a raw </script>.\nconst ldHtml = o => `<script type=\"application/ld+json\" data-mint-seo=\"edge\">${JSON.stringify(o).replace(/</g, '\\\\u003c')}</script>`;\n\n/**\n * The page with Mint's head (set tags replace the page's; fill tags only fill gaps) and, unless the page has it\n * already, Mint's script before </body>.\n */\nconst rewrite = (res, { head, script }) => {\n\tconst tags = head?.found ? head.tags || [] : [];\n\tconst seen = new Set();\n\tlet hasScript = false;\n\tlet rw = new HTMLRewriter();\n\ttags.forEach((t, i) => {\n\t\trw = rw.on(selectorOf(t), {\n\t\t\telement(el) {\n\t\t\t\tif (t.mode === 'set') el.remove();\n\t\t\t\telse seen.add(i);\n\t\t\t},\n\t\t});\n\t});\n\trw = rw\n\t\t.on('script[src*=\"track.js\"][data-key]', {\n\t\t\telement() {\n\t\t\t\thasScript = true;\n\t\t\t},\n\t\t})\n\t\t.on('head', {\n\t\t\telement(el) {\n\t\t\t\tel.onEndTag(end => {\n\t\t\t\t\tconst add = tags.filter((t, i) => t.mode === 'set' || !seen.has(i)).map(tagHtml);\n\t\t\t\t\tfor (const o of head?.found ? head.jsonLd || [] : []) add.push(ldHtml(o));\n\t\t\t\t\tif (add.length) end.before(add.join(''), { html: true });\n\t\t\t\t});\n\t\t\t},\n\t\t})\n\t\t.on('body', {\n\t\t\telement(el) {\n\t\t\t\tif (!script) return;\n\t\t\t\tel.onEndTag(end => {\n\t\t\t\t\tif (!hasScript) end.before(script, { html: true });\n\t\t\t\t});\n\t\t\t},\n\t\t});\n\tconst out = rw.transform(res);\n\tconst marked = new Response(out.body, out);\n\tmarked.headers.set('x-mint-edge', `${VERSION}${tags.length ? '; seo' : ''}`);\n\treturn marked;\n};\n\n/* ------------------------------------------------------------ the Worker */\n\nexport default {\n\tasync fetch(request, env, ctx) {\n\t\tconst url = new URL(request.url);\n\t\tif (!env.MINT_KEY) return toOrigin(request, env, url);\n\t\t// Mint's before/after check: this one request as if the Worker weren't there.\n\t\tif (env.BYPASS_SECRET && url.searchParams.get('mint-bypass') === env.BYPASS_SECRET) {\n\t\t\turl.searchParams.delete('mint-bypass');\n\t\t\treturn toOrigin(new Request(url, request), env, url);\n\t\t}\n\t\ttry {\n\t\t\tif (url.pathname.startsWith('/_mint/')) return await mintRoute(request, env, url);\n\t\t} catch {\n\t\t\treturn new Response('Mint is unavailable', { status: 503 });\n\t\t}\n\n\t\tconst config = await configOf(env, ctx);\n\t\tconst dev = env.MINT_DEV === '1';\n\t\tif (!config || config.bypass || !hostAllowed(url.host, config.domains, dev)) return toOrigin(request, env, url);\n\t\tconst key = pathKey(url.pathname);\n\t\tconst reading = request.method === 'GET' || request.method === 'HEAD';\n\n\t\tif (reading) {\n\t\t\tconst to = (config.redirects || []).find(r => r.from === key);\n\t\t\tif (to) {\n\t\t\t\tconst target = new URL(to.to, url.origin);\n\t\t\t\tif (!to.to.includes('?')) target.search = url.search;\n\t\t\t\treturn Response.redirect(target.href, to.permanent ? 301 : 302);\n\t\t\t}\n\t\t\tif ((config.robots && url.pathname === '/robots.txt') || (config.sitemap && url.pathname === '/sitemap.xml')) {\n\t\t\t\t// The sitemap's numbered parts past 5,000 addresses: /sitemap.xml?part=2 (backend docs/seo SEO-08).\n\t\t\t\tconst part = url.searchParams.get('part');\n\t\t\t\tconst extra =\n\t\t\t\t\turl.pathname === '/sitemap.xml' ? `&origin=${encodeURIComponent(url.origin)}${part && /^\\d{1,4}$/.test(part) ? `&part=${part}` : ''}` : '';\n\t\t\t\ttry {\n\t\t\t\t\tconst res = await withTimeout(fetch(`${apiOf(env)}/site${url.pathname}?apiKey=${encodeURIComponent(env.MINT_KEY)}${extra}`), WAIT_MS);\n\t\t\t\t\tif (res.ok) return new Response(res.body, { headers: { 'content-type': res.headers.get('content-type') || 'text/plain', 'cache-control': 'public, max-age=300', 'x-mint-edge': VERSION } });\n\t\t\t\t} catch {\n\t\t\t\t\t/* the site's own, below */\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// Ask for the head while the site's server answers.\n\t\tconst mintPage = request.method === 'GET' && (config.pages || []).includes(key);\n\t\tconst [res, head] = await Promise.all([toOrigin(request, env, url), mintPage ? headOf(env, ctx, key) : null]);\n\n\t\tconst type = res.headers.get('content-type') || '';\n\t\tconst size = Number(res.headers.get('content-length') || 0);\n\t\tif (request.method !== 'GET' || res.status !== 200 || !/text\\/html/i.test(type) || size > MAX_REWRITE) return res;\n\t\tconst script = `<script src=\"/_mint/track.js\" data-key=\"${esc(env.MINT_KEY)}\" data-api=\"/_mint/api\" data-seo${config.analytics === false ? ' data-no-track' : ''} defer></script>`;\n\t\treturn rewrite(res, { head, script });\n\t},\n};\n";
